const toWords=(specs:Spec[],topic:string,prefix:string):ObjectWord[]=>specs.map(([id,de,tr,description,descriptionTr,,note])=>({
 id,de,tr,description,descriptionTr,...(note?{note}:{}),topic,image:'/objects/toon/'+prefix+'-'+id+'.webp',extra:true,
}));
export const everydayObjectAdditions:ObjectWord[]=[...toWords(food,'objects-food','essen'),...toWords(drinks,'objects-drinks','getraenke'),...toWords(cooking,'objects-cooking','kueche'),...toWords(school,'objects-school','schule'),...toWords(outdoors,'objects-outdoors','draussen'),...toWords(teeth,'objects-body','koerper')];
const all=[...food,...drinks,...cooking,...school,...outdoors,...teeth];
export const everydayObjectMeanings:Record<string,readonly [en:string,ar:string,uk:string,fr:string]>=Object.fromEntries(
 all.map(([id,,,,,meanings])=>[id,meanings.slice(0,4) as unknown as readonly [string,string,string,string]]),
);
export const everydayExtraMeanings:Record<string,readonly [es:string,ru:string,fa:string,pl:string,it:string,pt:string]>=Object.fromEntries(
 all.map(([id,,,,,meanings])=>[id,meanings.slice(4) as unknown as readonly [string,string,string,string,string,string]]),
);
